from openpyxl import load_workbook

wb = load_workbook("budget.xlsx", data_only=False)
ws = wb["Budget"]
print("dims:", ws.dimensions, "max_row:", ws.max_row, "max_col:", ws.max_column)
formulas = []
for row in ws.iter_rows():
    for c in row:
        if isinstance(c.value, str) and c.value.startswith("="):
            formulas.append((c.coordinate, c.value))
print("FORMULAS:", formulas)
# Print all cells with values
for row in ws.iter_rows():
    for c in row:
        if c.value is not None:
            print(c.coordinate, repr(c.value))

# Compute total expenses from the expense line items (Excel rows 11-22, column C)
total = 0.0
count = 0
for r in range(11, 23):
    v = ws.cell(row=r, column=3).value
    if isinstance(v, (int, float)):
        total += v
        count += 1
print("EXPENSE_LINE_ITEMS:", count, "TOTAL:", round(total, 2))

